        const rawUrl=doc?.url||doc?.source_url||ref.source_url,u=rawUrl?safeUrl(rawUrl):null;
        if(u){const a=n('a','查看原文 ↗','rw-button');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';host.append(a);}else host.append(notice('该项原件链接尚未取得，请先核对其文档及定位信息。'));
