          const item=n('details',null,'rw-evidence-binding'),summary=n('summary'),doc=findDocument(binding);item.dataset.evidenceField=binding.field||'';
          summary.append(n('span',binding.label||labels[binding.field]||FIELD_LABELS[binding.field]||labelFor(binding.field||'')),n('small',documentName(doc)+' · '+locatorText(binding.locator),'rw-muted'));
